// goal: Lazy tool loader with preload and loading states
// eff: Dynamic import + hover preload + skeleton fallback
// inv: Panel mapping auto-generated by `bun run generate-registry`

import React, { Suspense, useCallback, useEffect, useRef } from 'react';
import { Card } from '@nexus/ui-kit';
import type { ToolId } from '../../kernel';
import { generatedToolPanels, type LoadableToolId } from '../_generated-tool-loader';

const PRELOAD_DELAY = 150; // ms before preload on hover

// Preload cache to avoid duplicate preloads
const preloadedTools = new Set<string>();

// rule: trigger React.lazy's underlying dynamic import. The previous
// `Promise.resolve(LazyPanel)` only wrapped the lazy component object in an
// already-resolved promise — React.lazy never started the dynamic import, so
// the preload was a complete no-op. React.lazy components expose their import
// thunk at `_payload._result` (with `_status === -1` meaning "not yet started");
// calling `_init(_payload)` kicks off the import. This internal shape has been
// stable across React 18.x.
function preloadLazyComponent(LazyPanel: unknown): void {
	if (typeof LazyPanel !== 'object' || LazyPanel === null) return;
	const lazy = LazyPanel as {
		_payload?: { _status?: number; _result?: unknown };
		_init?: (payload: unknown) => unknown;
	};
	const payload = lazy._payload;
	if (!payload || payload._status !== -1 || typeof payload._result !== 'function') return;
	if (typeof lazy._init !== 'function') return;
	lazy._init(payload);
}

// Skeleton loading component
const LoadingSkeleton: React.FC = () => (
	<Card variant="default" padding="md">
		<div style={{ display: 'flex', flexDirection: 'column', gap: '12px', alignItems: 'center', padding: '24px' }}>
			<div style={{ width: '40px', height: '40px', borderRadius: '50%', background: 'var(--halo-bg-tertiary)', animation: 'pulse 1.5s infinite' }} />
			<div style={{ width: '120px', height: '12px', borderRadius: '6px', background: 'var(--halo-bg-tertiary)', animation: 'pulse 1.5s infinite' }} />
			<div style={{ width: '180px', height: '10px', borderRadius: '5px', background: 'var(--halo-bg-tertiary)', animation: 'pulse 1.5s infinite', opacity: 0.6 }} />
		</div>
		<style>{`
			@keyframes pulse {
				0%, 100% { opacity: 1; }
				50% { opacity: 0.5; }
			}
		`}</style>
	</Card>
);

interface LazyToolRendererProps {
	toolId: ToolId | null;
	fallback?: React.ReactNode;
}

import { ToolErrorBoundary } from './ToolErrorBoundary';

export const LazyToolRenderer: React.FC<LazyToolRendererProps & { [key: string]: any }> = ({ toolId, fallback, ...props }) => {
	if (!toolId || !(toolId in generatedToolPanels)) {
		return fallback ? <>{fallback}</> : null;
	}

	const Panel = generatedToolPanels[toolId as LoadableToolId] as React.ComponentType<any>;
	return (
		<ToolErrorBoundary toolId={toolId}>
			<Suspense fallback={<LoadingSkeleton />}>
				<Panel {...props} />
			</Suspense>
		</ToolErrorBoundary>
	);
};


// Preload hook for hover behavior
export const useToolPreload = () => {
	const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

	const preload = useCallback((toolId: ToolId) => {
		if (preloadedTools.has(toolId) || !(toolId in generatedToolPanels)) return;

		timerRef.current = setTimeout(() => {
			try {
				const LazyPanel = generatedToolPanels[toolId as LoadableToolId];
				if (LazyPanel) {
					preloadLazyComponent(LazyPanel);
				}
				preloadedTools.add(toolId);
			} catch { /* ignore preload failures */ }
		}, PRELOAD_DELAY);
	}, []);

	const cancelPreload = useCallback(() => {
		if (timerRef.current) {
			clearTimeout(timerRef.current);
			timerRef.current = null;
		}
	}, []);

	useEffect(() => () => cancelPreload(), [cancelPreload]);

	return { preload, cancelPreload };
};

// Get available tool IDs from generated registry
export const getLoadableToolIds = (): ToolId[] => Object.keys(generatedToolPanels) as ToolId[];

/**
 * Batch preload top N tools on browser idle
 * @param toolIds Tools to preload, sorted by priority (e.g., by usage count)
 * @param count Number of tools to preload (default: 5)
 */
export function preloadToolsOnIdle(toolIds: ToolId[], count = 5): void {
	const toPreload = toolIds
		.filter(id => !preloadedTools.has(id) && id in generatedToolPanels)
		.slice(0, count);

	if (toPreload.length === 0) return;

	// Use requestIdleCallback if available, fallback to setTimeout
	const scheduleIdle = typeof requestIdleCallback !== 'undefined' 
		? requestIdleCallback 
		: (cb: () => void) => setTimeout(cb, 200);

	scheduleIdle(() => {
			toPreload.forEach((toolId, index) => {
				// Stagger preloads to avoid blocking
				setTimeout(() => {
					try {
						const LazyPanel = generatedToolPanels[toolId as LoadableToolId];
						if (LazyPanel) preloadLazyComponent(LazyPanel);
						preloadedTools.add(toolId);
					} catch { /* ignore */ }
				}, index * 50); // 50ms between each preload
			});
		});
}

/**
 * Hook for idle preloading - call once at app init
 */
export function useIdlePreload(priorityToolIds: ToolId[], count = 5) {
	useEffect(() => {
		// Delay to let main UI render first
		const timer = setTimeout(() => {
			preloadToolsOnIdle(priorityToolIds, count);
		}, 1000);
		return () => clearTimeout(timer);
	}, [priorityToolIds, count]);
}
